// Bygger den rigtige graf-query ud fra søgetypen: paragraf, emne eller part
const type = String($json.soegetype || '').trim().toLowerCase();
const vaerdi = String($json.vaerdi || '').trim();

const QUERIES = {
  paragraf: `
MATCH (p:Paragraf {nr: $vaerdi})
OPTIONAL MATCH (k:Kapitel)-[:HAR_PARAGRAF]->(p)
RETURN p.nr AS nr, p.overskrift AS overskrift, p.kilde AS kilde,
  k.nr AS kapitel, k.titel AS kapitel_titel,
  COLLECT { MATCH (p)-[:HAR_STYKKE]->(s:Stykke) RETURN {stk: s.stk, tekst: s.tekst} ORDER BY s.stk } AS stykker,
  COLLECT { MATCH (p)-[:HANDLER_OM]->(e:Emne) RETURN e.navn } AS emner,
  COLLECT { MATCH (p)-[r:GIVER_RET]->(a:Part) RETURN a.navn + ': ' + coalesce(r.beskrivelse, '') } AS rettigheder,
  COLLECT { MATCH (p)-[r:PAALAEGGER_PLIGT]->(a:Part) RETURN a.navn + ': ' + coalesce(r.beskrivelse, '') } AS pligter,
  COLLECT { MATCH (p)-[:FASTSAETTER_FRIST]->(f:Frist) RETURN coalesce(f.varighed, '') + ' – ' + coalesce(f.beskrivelse, '') } AS frister,
  COLLECT { MATCH (p)-[:DEFINERER]->(b:Begreb) RETURN b.navn + ': ' + coalesce(b.definition, '') } AS begreber,
  COLLECT { MATCH (p)-[:HENVISER_TIL]->(q:Paragraf) RETURN q.nr } AS henviser_til,
  COLLECT { MATCH (q:Paragraf)-[:HENVISER_TIL]->(p) RETURN q.nr } AS henvist_fra`,

  emne: `
MATCH (e:Emne)<-[:HANDLER_OM]-(p:Paragraf)
WHERE toLower(e.navn) CONTAINS toLower($vaerdi)
RETURN e.navn AS emne, p.nr AS nr, p.overskrift AS overskrift, p.kilde AS kilde,
  COLLECT { MATCH (p)-[r:GIVER_RET]->(a:Part) RETURN a.navn + ': ' + coalesce(r.beskrivelse, '') } AS rettigheder,
  COLLECT { MATCH (p)-[r:PAALAEGGER_PLIGT]->(a:Part) RETURN a.navn + ': ' + coalesce(r.beskrivelse, '') } AS pligter,
  COLLECT { MATCH (p)-[:FASTSAETTER_FRIST]->(f:Frist) RETURN coalesce(f.varighed, '') + ' – ' + coalesce(f.beskrivelse, '') } AS frister
ORDER BY toInteger(split(p.nr, ' ')[0]), p.nr`,

  part: `
MATCH (p:Paragraf)-[r:GIVER_RET|PAALAEGGER_PLIGT]->(a:Part)
WHERE toLower(a.navn) = toLower($vaerdi)
RETURN a.navn AS part, type(r) AS type, p.nr AS nr, p.overskrift AS overskrift,
  r.beskrivelse AS beskrivelse, p.kilde AS kilde
ORDER BY type, toInteger(split(p.nr, ' ')[0]), p.nr`,
};

if (!QUERIES[type]) {
  return { json: { fejl: `Ukendt soegetype "${type}". Brug "paragraf", "emne" eller "part".` } };
}

// "§ 59" → "59", "59a" → "59 a"
let v = vaerdi;
if (type === 'paragraf') {
  const m = vaerdi.replace(/§/g, '').trim().toLowerCase().match(/^(\d+)\s*([a-z])?$/);
  v = m ? m[1] + (m[2] ? ' ' + m[2] : '') : vaerdi;
}

return { json: { soegetype: type, vaerdi: v, payload: { statement: QUERIES[type], parameters: { vaerdi: v } } } };

// Gør grafens svar læsbart for agenten, med kilde på hvert fund
const { soegetype, vaerdi, fejl } = $('Byg graf-query').first().json;
if (fejl) return [{ json: { resultat: fejl } }];

const svar = $input.first().json;
if (svar.errors?.length || svar.error) {
  return [{ json: { resultat: 'Fejl fra Neo4j: ' + JSON.stringify(svar.errors || svar.error).slice(0, 300) } }];
}
const { fields, values } = svar.data;
const rows = values.map(v => Object.fromEntries(fields.map((f, i) => [f, v[i]])));
const liste = (titel, arr) => (arr && arr.length ? `${titel}:\n${arr.map(x => '- ' + x).join('\n')}` : null);

if (!rows.length) {
  const hjælp = {
    paragraf: 'Paragraffen findes ikke. Lejeloven har §§ 1-213.',
    emne: 'Ingen paragraffer om det emne. Gyldige emner er fx: Depositum og forudbetalt leje, Opsigelse, Fraflytning, Vedligeholdelse, Mangler, Fremleje og bytte, Husleje og lejefastsættelse.',
    part: 'Ukendt part. Brug: Lejer, Udlejer, Huslejenævn, Boligret, Kommune eller Beboerrepræsentation.',
  };
  return [{ json: { resultat: `Intet fundet for ${soegetype} "${vaerdi}". ${hjælp[soegetype]}` } }];
}

let resultat;
if (soegetype === 'paragraf') {
  const r = rows[0];
  const stykker = (r.stykker || [])
    .map(s => s.properties || s)
    .map(s => `Stk. ${s.stk}. ${s.tekst}`).join('\n');
  resultat = [
    `Lejeloven § ${r.nr}${r.overskrift ? ' – ' + r.overskrift : ''} (kapitel ${r.kapitel}: ${r.kapitel_titel})`,
    stykker,
    liste('Emner', r.emner),
    liste('Rettigheder', r.rettigheder),
    liste('Pligter', r.pligter),
    liste('Frister', r.frister),
    liste('Begreber', r.begreber),
    r.henviser_til?.length ? `Henviser til: ${r.henviser_til.map(n => '§ ' + n).join(', ')}` : null,
    r.henvist_fra?.length ? `Henvist til fra: ${r.henvist_fra.map(n => '§ ' + n).join(', ')}` : null,
    `Kilde: ${r.kilde}`,
  ].filter(Boolean).join('\n\n');
} else if (soegetype === 'emne') {
  resultat = `${rows.length} paragraffer om "${rows[0].emne}":\n\n` + rows.map(r => [
    `§ ${r.nr}${r.overskrift ? ' – ' + r.overskrift : ''}`,
    ...r.rettigheder.map(x => '  Ret: ' + x),
    ...r.pligter.map(x => '  Pligt: ' + x),
    ...r.frister.map(x => '  Frist: ' + x),
  ].join('\n')).join('\n') + `\n\nKilde: ${rows[0].kilde}`;
} else {
  const ret = rows.filter(r => r.type === 'GIVER_RET');
  const pligt = rows.filter(r => r.type === 'PAALAEGGER_PLIGT');
  const linje = r => `- § ${r.nr}: ${r.beskrivelse}`;
  resultat = [
    `${rows[0].part} i lejeloven`,
    ret.length ? `Rettigheder (${ret.length}):\n${ret.map(linje).join('\n')}` : null,
    pligt.length ? `Pligter (${pligt.length}):\n${pligt.map(linje).join('\n')}` : null,
    `Kilde: ${rows[0].kilde}`,
  ].filter(Boolean).join('\n\n');
}

return [{ json: { resultat, antal_fund: rows.length } }];
